import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AccountLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");
        String sortBy = req.getParameter("sort");

        // Input validation - only allow alphanumeric account IDs
        if (accountId == null || !accountId.matches("^[a-zA-Z0-9]{1,20}$")) {
            resp.sendError(400, "Invalid account ID format");
            return;
        }

        // Whitelist allowed field names
        String[] allowedFields = {"name", "email", "balance", "created_at", "status"};
        String selectedFields = "name, email, balance";
        if (fields != null) {
            StringBuilder sb = new StringBuilder();
            for (String f : fields.split(",")) {
                String trimmed = f.trim();
                boolean allowed = false;
                for (String af : allowedFields) {
                    if (af.equals(trimmed)) { allowed = true; break; }
                }
                if (allowed) {
                    if (sb.length() > 0) sb.append(", ");
                    sb.append(trimmed);
                }
            }
            if (sb.length() > 0) selectedFields = sb.toString();
        }

        // Sort parameter - validated against column names but uses string concat
        // for ORDER BY since PreparedStatement doesn't support parameterized ORDER BY
        String orderClause = "";
        if (sortBy != null && !sortBy.isEmpty()) {
            // Strip obvious injection attempts
            sortBy = sortBy.replaceAll("[;'\"]", "");
            orderClause = " ORDER BY " + sortBy;
        }

        String query = "SELECT " + selectedFields + " FROM accounts WHERE account_id = ?" + orderClause;
        logger.info("Executing query for account: " + accountId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, accountId);
            ResultSet rs = stmt.executeQuery();

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch lookup - accepts JSON body with array of IDs
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        try {
            JSONObject payload = new JSONObject(body.toString());
            JSONArray ids = payload.getJSONArray("account_ids");
            String callback = payload.optString("callback_url", null);

            // Process batch - limited to 50
            if (ids.length() > 50) {
                resp.sendError(400, "Maximum 50 accounts per batch");
                return;
            }

            resp.setContentType("application/json");
            resp.getWriter().write("{\"status\": \"processing\", \"count\": " + ids.length() + "}");

        } catch (JSONException e) {
            resp.sendError(400, "Invalid JSON payload");
        }
    }
}
